<?php
namespace Tests\Feature;
use App\Models\{User,OptimizationRun};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
final class ArchivedScenarioComparisonTest extends TestCase{
 use DatabaseTransactions;
 private function record(User $u,float $spend,float $response,array $sourceRows=[['day'=>'fixture']]):OptimizationRun{foreach($sourceRows as&$row){$row['provider']='google';$row['metadata']=['outcome_contract'=>['version'=>'source-outcomes-1','provider'=>'google','count_metric'=>'synthetic-purchase','value_metric'=>'synthetic-purchase-value','attribution_basis'=>'synthetic-only','value_truth'=>'provider_reported_not_verified_sales','cross_source_equivalence'=>false],'normalization_version'=>'strict-operands-1','account_metadata_source'=>'provider-discovery-explicit-1'];}unset($row);$s=['source_rows'=>$sourceRows,'accounts'=>[['id'=>1]],'channels'=>[['channel'=>'a','curve'=>['name'=>'linear','params'=>['a'=>2]],'min'=>0,'max'=>$spend]]];return OptimizationRun::create(['user_id'=>$u->id,'engine'=>'entity','engine_version'=>'fixture','status'=>'ok','input_hash'=>str_repeat('a',64),'inputs'=>['budget'=>$spend],'dataset_fingerprint'=>[],'source_snapshot'=>$s,'snapshot_sha256'=>hash('sha256',json_encode($s)),'result'=>['status'=>'ok','objective'=>'MAXIMIZE_REVENUE','response_metric'=>'conversion_value','entity_level'=>'campaign','currency'=>'USD','timezone'=>'UTC','window'=>['start'=>'2026-11-01','end'=>'2026-11-30'],'period_days'=>30,'scenario_total_spend'=>$spend,'scenario_response'=>$response,'allocations'=>[['entity_key'=>'a','scenario_spend'=>$spend]]]]);}
 public function test_same_curve_source_comparison_retains_unequal_spend_and_is_owner_scoped():void{$u=User::factory()->create();$a=$this->record($u,50,100);$b=$this->record($u,80,160);$url='/api/v1/analytics/optimization-runs/'.$a->id.'/compare';$this->actingAs($u,'sanctum')->postJson($url,['other_run_id'=>$b->id])->assertOk()->assertJsonPath('data.status','ok')->assertJsonPath('data.same_total_spend',false)->assertJsonPath('data.spend_change',30)->assertJsonPath('data.modeled_response_change',60)->assertJsonPath('data.second.budget',80);$foreign=$this->record(User::factory()->create(),80,160);$this->postJson($url,['other_run_id'=>$foreign->id])->assertNotFound();}
 public function test_changed_source_or_result_abstains_not_a_computed_gain():void{$u=User::factory()->create();$a=$this->record($u,50,100);$b=$this->record($u,50,100,[['day'=>'different']]);$url='/api/v1/analytics/optimization-runs/'.$a->id.'/compare';$this->actingAs($u,'sanctum')->postJson($url,['other_run_id'=>$b->id])->assertJsonPath('data.status','not_comparable')->assertJsonMissingPath('data.modeled_response_change');$b->update(['result'=>['status'=>'changed']]);$this->postJson($url,['other_run_id'=>$b->id])->assertJsonPath('data.status','not_comparable');}
}
